"use strict";exports.id=8606,exports.ids=[8606],exports.modules={78606:(e,t,i)=>{i.d(t,{Iv:()=>n,qJ:()=>a});let n=[{ipc:"IPC 302",ipcTitle:"Murder",bns:"BNS 103",bnsTitle:"Punishment for Murder (Includes mob lynching sub-clause)",status:"Changed Section Number"},{ipc:"IPC 420",ipcTitle:"Cheating and dishonestly inducing delivery of property",bns:"BNS 318",bnsTitle:"Cheating",status:"Renumbered"},{ipc:"IPC 124A",ipcTitle:"Sedition",bns:"BNS 152",bnsTitle:"Act endangering sovereignty, unity and integrity of India",status:"Substantially Revised"},{ipc:"IPC 375 / 376",ipcTitle:"Rape & Punishment",bns:"BNS 63 / 64",bnsTitle:"Rape & Punishment for Rape",status:"Renumbered & Enhanced"},{ipc:"IPC 304A",ipcTitle:"Causing death by negligence",bns:"BNS 106",bnsTitle:"Causing death by negligence (Strict hit-and-run penalty)",status:"Enhanced Penalty"},{ipc:"IPC 141 / 143",ipcTitle:"Unlawful Assembly",bns:"BNS 189",bnsTitle:"Unlawful Assembly",status:"Renumbered"},{ipc:"IPC 498A",ipcTitle:"Cruelty by husband or relatives",bns:"BNS 85 / 86",bnsTitle:"Cruelty against woman by husband or relative",status:"Renumbered"},{ipc:"IPC 307",ipcTitle:"Attempt to Murder",bns:"BNS 109",bnsTitle:"Attempt to Murder",status:"Renumbered"},{ipc:"IPC 378 / 379",ipcTitle:"Theft & Punishment",bns:"BNS 303",bnsTitle:"Theft",status:"Renumbered"},{ipc:"IPC 506",ipcTitle:"Criminal Intimidation",bns:"BNS 351",bnsTitle:"Criminal Intimidation",status:"Renumbered"}],a=[{id:"kesavananda-bharati",title:"Kesavananda Bharati v. State of Kerala (1973)",citation:"(1973) 4 SCC 225",bench:"13 Judges (7:6 Majority)",subject:"Constitutional Law",keyPrinciple:"Basic Structure Doctrine",facts:"Petitioner challenged Kerala Land Reforms Act restricting property rights of religious matha.",ratio:"Parliament has wide powers to amend the Constitution under Article 368, but cannot alter or destroy its Basic Structure (Judicial review, Secularism, Federalism, Rule of Law).",importance:"Most celebrated judgment in Indian Constitutional history."},{id:"maneka-gandhi",title:"Maneka Gandhi v. Union of India (1978)",citation:"AIR 1978 SC 597",bench:"7 Judges",subject:"Constitutional Law",keyPrinciple:"Due Process of Law & Golden Triangle (Art 14, 19, 21)",facts:"Passport impounded under Passport Act without providing reasons or hearing.",ratio:"Procedure established by law under Art 21 must not be arbitrary, unfair or unreasonable. Articles 14, 19, and 21 are inter-connected.",importance:"Transformed Article 21 into an expanding horizon of human rights."},{id:"navtej-singh-johar",title:"Navtej Singh Johar v. Union of India (2018)",citation:"(2018) 10 SCC 1",bench:"5 Judges",subject:"Constitutional Law & Criminal Law",keyPrinciple:"Decriminalization of Homosexuality (Section 377)",facts:"Challenge to Section 377 IPC criminalizing consensual adult sexual relationships.",ratio:"Section 377 in so far as it penalizes consensual sexual acts between adults in private violates Art 14, 15, 19, and 21.",importance:"Monumental victory for LGBTQIA+ rights and constitutional morality."},{id:"vishaka",title:"Vishaka v. State of Rajasthan (1997)",citation:"AIR 1997 SC 3011",bench:"3 Judges",subject:"Labour & Constitutional Law",keyPrinciple:"Prevention of Sexual Harassment at Workplace",facts:"Bhanwari Devi gang rape incident exposed lack of workplace safety for women.",ratio:"Supreme Court laid down binding guidelines (Vishaka Guidelines) under Art 141 using CEDAW convention until Parliament enacted PoSH Act 2013.",importance:"Judicial law-making for gender equality at workplace."}]}};